from typing import List
class Solution:
    def shuffle(self, nums: List[int], n: int) -> List[int]:
        def index(i):
            return 2*i if i < n else 2*(i-n)+1

        for i in range(len(nums)):
            j = i
            while nums[i] >= 0:
                j = index(j)
                nums[i], nums[j] = nums[j], ~nums[i]  # processed
        for i in range(len(nums)):
            nums[i] = ~nums[i]
        return nums

